// Skill Galaxy — Life Lagoon and Matter Moon questions.
// Questions written for Skill Galaxy; topics from the Marble Skill Taxonomy (CC BY-SA 4.0).
SG_Q({
  // ===================== LIFE LAGOON =====================

  // The Circulatory System
  "mt_BX4D8cCFtQ": [
    { q: "Which organ pumps blood all around the body?", a: ["The heart", "The lungs", "The liver", "The brain"], why: "The heart is a muscular pump. Each beat squeezes blood out into the blood vessels, and the blood travels all round the body and back again." },
    { q: "Which blood vessels carry blood **away** from the heart?", a: ["Arteries", "Veins", "Capillaries", "Nerves"], why: "Arteries carry blood away from the heart (think A for away). Veins bring blood back to the heart. Nerves are not blood vessels at all." },
    { q: "Which are the tiniest blood vessels, with walls so thin that oxygen can pass through them into the body's cells?", a: ["Capillaries", "Arteries", "Veins", "Valves"], why: "Capillaries are thinner than a hair. Oxygen and nutrients pass out through their walls into cells, and waste such as carbon dioxide passes back in." },
    { q: "Victoria says, \"Blood only carries oxygen around the body.\" What has she left out?", a: ["It also carries nutrients and waste", "It also carries undigested food", "It also carries air bubbles", "Nothing — oxygen is all it carries"], why: "Blood also carries nutrients from digested food to every cell, and carries waste such as carbon dioxide away from them." },
    { q: "Which waste gas does blood carry from the body's cells to the lungs, so it can be breathed out?", a: ["Carbon dioxide", "Oxygen", "Nitrogen", "Hydrogen"], why: "Cells make carbon dioxide as waste when they release energy from food. Blood carries it to the lungs, where it is breathed out." },
    { q: "Blood leaves the heart and passes through three kinds of blood vessel before it gets back. In which order?", a: ["Arteries → capillaries → veins", "Veins → capillaries → arteries", "Capillaries → arteries → veins", "Arteries → veins → capillaries"], why: "Arteries carry blood away from the heart, capillaries take it close to the cells, and veins bring it back. The same blood goes round and round in a loop." },
    { q: "After running for the bus, Anya's heart is beating much faster. Why?", a: ["Her muscles need more oxygen delivered", "Her heart is trying to cool itself down", "Her blood has suddenly become thicker", "Her lungs have stopped taking in air"], why: "Working muscles use oxygen and nutrients faster and make more carbon dioxide. The heart beats faster to move blood round more quickly." },
    { q: "When you feel your pulse at your wrist, what are you feeling?", a: ["Blood surging through an artery", "Blood flowing back along a vein", "A muscle in your wrist twitching", "Air moving through your blood"], why: "Each heartbeat pushes a surge of blood along the arteries. You can feel this as a pulse where an artery is close to the skin, as at the wrist." }
  ],

  // The Digestive System
  "mt_Ruk2-lyGPZ": [
    { q: "Where does digestion begin?", a: ["The mouth", "The stomach", "The small intestine", "The oesophagus"], why: "Digestion starts in the mouth. Teeth chew food into small pieces and saliva starts to break it down." },
    { q: "What is the job of the oesophagus?", a: ["Carries food from the mouth to the stomach", "Absorbs nutrients from food into the blood", "Takes air from the mouth down to the lungs", "Stores waste until it leaves the body"], why: "The oesophagus (food pipe) is a muscular tube that squeezes food down to the stomach. Air goes down a different tube, the windpipe." },
    { q: "Which part of the digestive system does food pass into straight after the small intestine?", a: ["Large intestine", "Stomach", "Oesophagus", "Mouth"], why: "The order is mouth, oesophagus, stomach, small intestine, large intestine. Food goes through the long small intestine first, then the large one." },
    { q: "In which organ are most nutrients from food absorbed into the blood?", a: ["Small intestine", "Stomach", "Large intestine", "Liver"], why: "Digested food passes through the walls of the small intestine into the blood, which carries the nutrients all round the body." },
    { q: "What does the stomach do to food?", a: ["Churns it up with acid and juices", "Absorbs most of its nutrients into blood", "Chews it into smaller pieces with teeth", "Removes water and stores the waste"], why: "The stomach's muscular walls churn the food, mixing it with acid and juices that break it down into a thick, soupy mixture." },
    { q: "What is the main job of the large intestine?", a: ["Absorbing water from leftover food", "Absorbing most of the nutrients", "Mixing food with stomach acid", "Chewing food into small pieces"], why: "By the time food reaches the large intestine most nutrients have gone. Water is absorbed here, leaving solid waste to leave the body." },
    { q: "Anya says, \"The small intestine is called small because it is the shortest part.\" Why is she wrong?", a: ["It is narrow but very long", "It is the widest part of the gut", "It is shorter than the oesophagus", "It is really part of the stomach"], why: "The small intestine is narrower than the large intestine but much longer — about 6 metres in an adult — giving lots of surface to absorb nutrients." },
    { q: "Why is it important to chew food well before you swallow it?", a: ["Chewing makes food easier to swallow and digest", "Chewing absorbs the nutrients into the blood", "Chewing removes the water from the food", "Chewing turns food straight into energy"], why: "Chewing breaks food into small pieces and mixes it with saliva. This makes it easier to swallow and gives digestive juices more surface to work on." }
  ],

  // Nutrients in a Healthy Diet
  "mt_sDmrVCfzqt": [
    { q: "Which nutrient is needed mainly for growth and repair of the body?", a: ["Protein", "Carbohydrate", "Fibre", "Water"], why: "Proteins are used to build and repair muscles, skin and other tissues. Meat, fish, eggs, beans and lentils are good sources." },
    { q: "Which of these foods is a good source of protein for a vegetarian?", a: ["Lentils", "Apples", "Rice cakes", "Lettuce"], why: "Lentils, beans, peas and chickpeas (pulses) are rich in protein. Apples and lettuce are mostly water, fibre and vitamins; rice cakes are mostly carbohydrate." },
    { q: "A healthy diet has seven parts: carbohydrates, proteins, fats, vitamins, minerals, fibre and which other?", a: ["Water", "Sugar", "Oxygen", "Caffeine"], why: "Water is the seventh. Most of your body is water, and you need it to carry substances around and keep cool. Sugar is a type of carbohydrate." },
    { q: "Which nutrient group is the body's main source of energy, found in bread, rice, pasta and potatoes?", a: ["Carbohydrates", "Vitamins", "Minerals", "Fibre"], why: "Carbohydrates such as starch and sugar are broken down into glucose, which cells use for energy. Starchy foods like bread and pasta are full of them." },
    { q: "What is the main job of dietary fibre?", a: ["Keeps food moving through the gut", "Builds and repairs muscles", "Gives the most energy per gram", "Carries oxygen in the blood"], why: "Fibre can't be digested, but it adds bulk that helps food move through the intestines and prevents constipation. Wholemeal bread, fruit and beans have lots." },
    { q: "Calcium, found in milk and cheese, is needed for strong bones and teeth. Which type of nutrient is calcium?", a: ["Mineral", "Vitamin", "Protein", "Carbohydrate"], why: "Calcium is a mineral. Minerals such as calcium and iron come from food in small amounts. Iron is needed to make red blood cells." },
    { q: "Which of these does **not** give the body any energy?", a: ["Vitamins", "Fats", "Carbohydrates", "Proteins"], why: "Carbohydrates, fats and proteins all provide energy. Vitamins, minerals, fibre and water are vital for health but give no energy." },
    { q: "Victoria says, \"Fat is bad for you, so a healthy diet should have none at all.\" What is wrong with this?", a: ["Fat is needed for energy and to keep warm", "Fat is a vitamin, so we need lots of it", "Fat is the body's main source of fibre", "Fat is only found in fruit and vegetables"], why: "Fats store lots of energy, help keep us warm and help the body use some vitamins. A healthy diet has some fat, just not too much." }
  ],

  // Cells Under the Microscope
  "mt_VfA4xo4kUv": [
    { q: "What are all living things made of?", a: ["Cells", "Crystals", "Fibres", "Grains"], why: "Every living thing — from a tiny bacterium to an oak tree to you — is made of one or more cells, the basic building blocks of life." },
    { q: "True or false: some living things are made of just one cell.", a: ["True", "False"], why: "Bacteria and many other micro-organisms, such as yeast, are made of a single cell. A human body is made of trillions of cells." },
    { q: "In a stained cheek cell, which part looks like a dark blob and controls what the cell does?", a: ["Nucleus", "Cytoplasm", "Cell membrane", "Cell wall"], why: "The nucleus holds the cell's instructions and controls its activities. It soaks up stain well, so it shows up as a dark spot." },
    { q: "Which part of a cell is the jelly-like substance where most of the cell's chemical reactions happen?", a: ["Cytoplasm", "Nucleus", "Cell membrane", "Vacuole"], why: "Cytoplasm fills the cell around the nucleus. Most of the chemical reactions that keep the cell alive happen in it." },
    { q: "What is the thin outer layer of a cheek cell that controls what goes in and out?", a: ["Cell membrane", "Cell wall", "Nucleus", "Cytoplasm"], why: "The cell membrane surrounds every cell and controls what enters and leaves. Animal cells such as cheek cells have no cell wall." },
    { q: "Why is a drop of iodine solution added to onion skin cells on a microscope slide?", a: ["To stain parts so they show up clearly", "To kill any germs living on the slide", "To make the cells swell up bigger", "To stop the glass slide steaming up"], why: "Cells are mostly see-through. A stain such as iodine colours parts of the cell, like the nucleus, so they are much easier to see." },
    { q: "When you start looking at a slide with a light microscope, which objective lens should you use first?", a: ["The lowest-power lens", "The highest-power lens", "The middle lens, always", "It makes no difference"], why: "Low power shows a wider area, so it's easier to find the cells and focus. Then you switch to a higher power to see more detail." },
    { q: "A microscope has a ×10 eyepiece lens and a ×40 objective lens. What is the total magnification?", a: ["×400", "×50", "×30", "×4"], why: "Multiply the two lenses together: 10 × 40 = 400. The cells look 400 times bigger than they really are." }
  ],

  // Parts of Plant and Animal Cells
  "mt_bABr-c2DfV": [
    { q: "Which part of a cell holds the genetic information and controls the cell's activities?", a: ["Nucleus", "Ribosome", "Vacuole", "Cell wall"], why: "The nucleus contains the genetic material (DNA), the instructions that control what the cell does and how it grows." },
    { q: "Which part of a cell is where respiration releases energy from glucose?", a: ["Mitochondria", "Chloroplasts", "Nucleus", "Ribosomes"], why: "Mitochondria are where aerobic respiration happens. They release energy from glucose for everything the cell does." },
    { q: "What is made in a cell's ribosomes?", a: ["Proteins", "Glucose", "Oxygen", "Fat"], why: "Ribosomes are tiny structures where the cell joins building blocks together to make proteins, which it needs for growth and repair." },
    { q: "Which of these parts is found in plant cells but **not** in animal cells?", a: ["Cell wall", "Cell membrane", "Nucleus", "Mitochondria"], why: "Plant cells have a strong cell wall made of cellulose outside the membrane. Animal cells have only a membrane. Both have a nucleus and mitochondria." },
    { q: "A plant cell has a large vacuole filled with cell sap. What is it mainly for?", a: ["Keeping the cell firm", "Making proteins", "Releasing energy", "Trapping sunlight"], why: "When the vacuole is full of sap it pushes outwards and keeps the cell firm, helping the plant stand up. Without water, plants wilt." },
    { q: "Chloroplasts contain a green substance. What do chloroplasts do?", a: ["Absorb light to make food", "Release energy from glucose", "Control what enters the cell", "Make proteins for growth"], why: "Chloroplasts contain chlorophyll, which absorbs light energy. The plant uses it to make glucose by photosynthesis." },
    { q: "Cells in a plant's roots are underground. Which part would you expect them **not** to have?", a: ["Chloroplasts", "Nucleus", "Cell wall", "Mitochondria"], why: "Root cells get no light, so chloroplasts would be no use there. They still need a nucleus, a cell wall and mitochondria for energy." },
    { q: "Muscle cells use a lot of energy. Which part would you expect them to have lots of?", a: ["Mitochondria", "Chloroplasts", "Vacuoles", "Cell walls"], why: "Mitochondria release energy from glucose by respiration, so cells that work hard, like muscle cells, have lots of them." }
  ],

  // Photosynthesis
  "mt_zM5vu31jgl": [
    { q: "Which gas do plants take in from the air for photosynthesis?", a: ["Carbon dioxide", "Oxygen", "Nitrogen", "Hydrogen"], why: "Plants take in carbon dioxide through tiny holes in their leaves and combine it with water to make glucose." },
    { q: "On a sunny day, pondweed gives off tiny bubbles of gas. Which gas is it?", a: ["Oxygen", "Carbon dioxide", "Steam", "Nitrogen"], why: "Oxygen is made by photosynthesis. The brighter the light, the faster the pondweed photosynthesises and the more bubbles you see." },
    { q: "Which green substance in chloroplasts absorbs the light energy needed for photosynthesis?", a: ["Chlorophyll", "Cellulose", "Glucose", "Starch"], why: "Chlorophyll is the green pigment in chloroplasts. It absorbs light energy, which the plant uses to make glucose." },
    { q: "Liam says, \"Plants get their food from the soil.\" What is the best correction?", a: ["Plants get their food by making their own", "Plants get their food from the rain", "Plants get their food from fertiliser", "Plants get their food from dead leaves"], why: "Plants make their own food (glucose) by photosynthesis. From the soil they take only water and minerals, which are not food." },
    { q: "What does a plant take in through its roots?", a: ["Water and minerals", "Carbon dioxide and light", "Glucose and oxygen", "Sugar and starch"], why: "Roots absorb water and mineral nutrients from the soil. Carbon dioxide comes from the air through the leaves, and light from the Sun." },
    { q: "Which is the word equation for photosynthesis? (Light energy is needed too.)", a: ["carbon dioxide + water → glucose + oxygen", "glucose + oxygen → carbon dioxide + water", "oxygen + water → glucose + carbon dioxide", "carbon dioxide + soil → glucose + oxygen"], why: "The raw materials are carbon dioxide and water; the products are glucose and oxygen. The reverse equation is respiration." },
    { q: "A plant is kept in a dark cupboard for two weeks but watered well. Why does it start to struggle?", a: ["It cannot photosynthesise without light", "It is getting far too much water", "It cannot take in any oxygen in the dark", "Its roots cannot take in minerals"], why: "Without light the plant can't photosynthesise, so it can't make new glucose. It uses up its stored food and becomes weak and pale." },
    { q: "Roots absorb mineral salts such as nitrates. Why do plants need them?", a: ["For healthy growth, e.g. making proteins", "As their main source of energy for growth", "To make carbon dioxide for their leaves", "To help the leaves absorb more light"], why: "Minerals are not food or energy. Plants need small amounts for healthy growth: nitrates, for example, are used to make proteins." }
  ],

  // Food Chains & Energy Transfer
  "mt_oB-L8EVdIP": [
    { q: "In a food chain, what is a producer?", a: ["A green plant that makes its own food", "An animal that eats only plants", "An animal that hunts other animals", "A fungus that breaks down waste"], why: "Producers, usually green plants, make their own food using energy from sunlight. Every food chain starts with a producer." },
    { q: "Which of these is a correct food chain?", a: ["grass → rabbit → fox", "fox → rabbit → grass", "rabbit → grass → fox", "grass → fox → rabbit"], why: "A food chain starts with a producer (grass). Arrows point to the animal doing the eating: the rabbit eats grass, the fox eats the rabbit." },
    { q: "Where does almost all the energy in a food chain first come from?", a: ["The Sun", "The soil", "Rainwater", "The top predator"], why: "Plants capture energy from sunlight to make food. That energy is then passed along the chain to each animal that eats." },
    { q: "In the food chain grass → grasshopper → frog → heron, what is the grasshopper?", a: ["Primary consumer", "Producer", "Top predator", "Decomposer"], why: "The grasshopper is the first animal in the chain and eats the producer (grass), so it is the primary consumer." },
    { q: "What do the arrows in a food chain show?", a: ["Energy passing from food to eater", "Which animal is bigger than the other", "Where each of the animals lives", "Which animal hunts in the night"], why: "Each arrow points from the thing being eaten to the thing that eats it, showing the direction energy flows." },
    { q: "In the food chain grass → rabbit → fox, all the foxes are removed. What would most likely happen to the rabbits at first?", a: ["Their numbers would go up", "Their numbers would go down", "Their numbers would stay the same", "They would all die out quickly"], why: "With no foxes hunting them, more rabbits survive, so numbers rise — at least until there isn't enough grass to feed them all." },
    { q: "In oak leaves → caterpillar → blue tit → sparrowhawk, which animal is both a predator and prey?", a: ["Blue tit", "Caterpillar", "Sparrowhawk", "Oak leaves"], why: "The blue tit hunts caterpillars, so it is a predator, but it is hunted by the sparrowhawk, so it is also prey." },
    { q: "Why are there usually far fewer foxes than rabbits in an area?", a: ["Energy is lost at each link in the chain", "Foxes need less food than rabbits do", "Foxes only need to eat once a year", "Rabbits are better at finding food"], why: "Only a small part (roughly a tenth) of the energy at each level passes to the next; the rest is used for moving and keeping warm. So less is left for each level up." }
  ],

  // Food Webs & Interdependence
  "mt_URTJbS3hhs": [
    { q: "What is a food web?", a: ["A set of food chains linked together", "A single chain of who eats who", "A spider's web used to trap food", "A list of the plants in a habitat"], why: "A food web joins up many food chains in a habitat, showing all the different feeding links between living things." },
    { q: "Why is a food web more realistic than a single food chain?", a: ["Most animals have more than one food", "Food webs leave out all the producers", "Most animals eat only one kind of food", "Food chains always include humans"], why: "Most animals eat several kinds of food and are eaten by several predators. A web shows all these links; a chain shows only one." },
    { q: "In a woodland, oak leaves are eaten by caterpillars, caterpillars by blue tits and wrens, and both birds by sparrowhawks. Which is the apex predator?", a: ["Sparrowhawk", "Blue tit", "Caterpillar", "Wren"], why: "An apex predator is at the top of the web: nothing else in the web eats it. Here, that is the sparrowhawk." },
    { q: "In a food web, what is a secondary consumer?", a: ["An animal that eats primary consumers", "An animal that eats only producers", "A plant that makes its own food", "A living thing that breaks down dead matter"], why: "Producers are eaten by primary consumers, and primary consumers are eaten by secondary consumers. A blue tit eating caterpillars is one." },
    { q: "In a field, owls eat mice and voles, and mice and voles eat seeds. A disease kills most of the owls. What happens to the mice at first?", a: ["Their numbers go up", "Their numbers go down", "Their numbers stay the same", "They all move to a new field"], why: "With fewer owls hunting them, more mice survive and breed, so their numbers rise. Later, they may run short of seeds." },
    { q: "Rabbits eat grass. Foxes and buzzards both eat rabbits. Which two animals are competing for the same food?", a: ["Foxes and buzzards", "Rabbits and foxes", "Grass and buzzards", "Rabbits and buzzards"], why: "Foxes and buzzards both hunt rabbits, so they compete for them. If the foxes increased, there could be fewer rabbits left for buzzards." },
    { q: "Bees pollinate apple blossom. A chemical kills most of the bees near an orchard. What is most likely to happen?", a: ["Fewer apples form on the trees", "The trees grow more apples", "Nothing, as trees don't need bees", "The apples grow much bigger"], why: "Apple flowers need insects such as bees to carry pollen before fruit can form. Living things depend on each other in more ways than just food." },
    { q: "Anya draws an arrow from a fox to a rabbit to show that the fox eats the rabbit. What should she change?", a: ["The arrow should point from rabbit to fox", "The arrow should be taken out altogether", "The fox should go at the bottom of the web", "The arrow should point both ways at once"], why: "Arrows show the flow of energy, so they point from the food to the animal that eats it: rabbit → fox." }
  ],

  // Classifying Organisms
  "mt_IY3KwGLZgk": [
    { q: "Which of these is a micro-organism?", a: ["A bacterium", "A ladybird", "A daisy", "A mushroom"], why: "Micro-organisms are living things too small to see without a microscope. Bacteria are micro-organisms; a mushroom is a fungus you can see." },
    { q: "Which feature do plants have that animals do not?", a: ["They make their own food", "They need water to live", "They grow and change", "They are made of cells"], why: "Green plants make their own food by photosynthesis. Animals have to eat their food. All living things need water, grow and are made of cells." },
    { q: "Which feature is shared by **all** animals?", a: ["They all have to eat food", "They all have a bony backbone", "They all have legs or wings", "They all breathe with lungs"], why: "Animals can't make their own food, so they must eat. Many have no backbone, legs or wings, and fish breathe with gills, not lungs." },
    { q: "A frog, a salmon, a robin and a fox all have a backbone. What are animals with a backbone called?", a: ["Vertebrates", "Invertebrates", "Mammals", "Amphibians"], why: "Animals with a backbone are vertebrates. The five vertebrate groups are fish, amphibians, reptiles, birds and mammals." },
    { q: "Which of these animals is an invertebrate (has no backbone)?", a: ["Snail", "Frog", "Trout", "Bat"], why: "Snails, worms, insects and spiders have no backbone, so they are invertebrates. Frogs, trout and bats are all vertebrates." },
    { q: "Liam says, \"A whale lives in the sea, so it must be a fish.\" Which feature shows that a whale is a mammal?", a: ["It breathes air and feeds young on milk", "It has fins and a tail for swimming", "It lives its whole life in salt water", "It can swim faster than most fish"], why: "Mammals breathe air with lungs and feed their young on milk. Whales do both. Fins and living in water don't decide the group." },
    { q: "Why are mushrooms not classed as plants?", a: ["They have no chlorophyll to make food", "They are always poisonous to eat", "They are really a kind of small animal", "They only ever grow in the dark"], why: "Mushrooms are fungi. They have no chlorophyll, so they can't make food by photosynthesis. They feed by breaking down dead or living material around them." },
    { q: "True or false: all micro-organisms are harmful and cause disease.", a: ["False", "True"], why: "Many micro-organisms are helpful: yeast makes bread rise, bacteria turn milk into yoghurt, and many break down dead material." }
  ],

  // How animals adapt to environments
  "mt_LRzjbo1Fn6": [
    { q: "What is an adaptation?", a: ["A feature that helps a living thing survive", "A change an animal decides to make itself", "The type of food an animal likes to eat", "The place where an animal chooses to live"], why: "An adaptation is a feature, such as thick fur or webbed feet, that helps a living thing survive in its habitat. Animals don't choose them." },
    { q: "Polar bears have thick fur and a layer of fat called blubber. How does this help them?", a: ["Keeps them warm in the freezing Arctic", "Helps them hide in the desert sand", "Makes them lighter for climbing trees", "Lets them breathe underwater"], why: "Thick fur and blubber trap heat, keeping polar bears warm on the ice and in icy Arctic water." },
    { q: "Why does a duck have webbed feet?", a: ["To push through water when swimming", "To grip branches tightly when perching", "To dig burrows in the soil", "To catch insects in the air"], why: "Webbed feet act like paddles, pushing lots of water back with each stroke so the duck swims well." },
    { q: "Mountain hares in the Scottish Highlands grow white fur in winter. How does this help them survive?", a: ["It camouflages them against snow", "It helps them find food in winter", "It makes them run much faster", "It helps them dig deeper burrows"], why: "White fur blends in with the snow, so predators such as golden eagles and foxes find them harder to spot." },
    { q: "A cactus has spines instead of broad, flat leaves. How does this help it in the desert?", a: ["It loses much less water this way", "It catches more sunlight", "It helps the cactus grow faster", "It keeps the cactus warm at night"], why: "Broad leaves lose lots of water. Thin spines lose very little, and they also protect the cactus's stored water from thirsty animals." },
    { q: "A fennec fox lives in the hot Sahara desert and has very large ears. How do big ears help it with the heat?", a: ["They give off heat to keep it cool", "They store water for dry days", "They soak up extra heat from the sun", "They shade its eyes from the sun"], why: "Big, thin ears have lots of blood vessels close to the surface, so heat escapes from the blood into the air, helping the fox stay cool." },
    { q: "Over many generations, how does a population of animals become better adapted?", a: ["Those with helpful features survive and breed more", "Animals change their own bodies on purpose", "Each animal grows new features when it needs them", "Parents teach their young how to grow features"], why: "Living things vary. Those with helpful features are more likely to survive and have young, passing the features on. Over many generations, this is evolution." },
    { q: "Victoria says, \"Giraffes stretched their necks to reach high leaves, so their babies were born with longer necks.\" What is wrong?", a: ["Changes in a lifetime aren't passed on", "Giraffes only eat grass on the ground", "Giraffes' necks are really quite short", "Long necks only grow in cold places"], why: "Stretching doesn't change what is passed to babies. Giraffes born with slightly longer necks reached more food, survived and bred more, so long necks became common." }
  ],

  // ===================== MATTER MOON =====================

  // Solids, Liquids & Gases
  "mt_YQkUdIHO8L": [
    { q: "Which of these describes a liquid?", a: ["Flows and takes its container's shape", "Keeps its own fixed shape and size", "Spreads out to fill any space it's in", "Can be squashed into a tiny space"], why: "Liquids flow and take the shape of whatever they are poured into, but keep the same volume. Gases spread out to fill a space." },
    { q: "Which of these is a gas at room temperature?", a: ["Oxygen", "Honey", "Salt", "Butter"], why: "Oxygen is a gas: it is part of the air we breathe. Honey is a thick liquid, while salt and butter are solids." },
    { q: "Which is a property of all solids?", a: ["They keep a fixed shape", "They flow when poured", "They fill the whole container", "They are always hard and heavy"], why: "Solids keep their own shape unless a force changes it. They aren't always hard or heavy: cotton wool and a feather are solids too." },
    { q: "Which list contains **only** solids?", a: ["Wood, ice, salt, sand", "Wood, milk, salt, sand", "Wood, ice, oxygen, sand", "Wood, ice, salt, honey"], why: "Wood, ice, salt and sand all keep their own shape. Milk and honey are liquids, and oxygen is a gas." },
    { q: "True or false: a sponge is a solid, even though you can squash it.", a: ["True", "False"], why: "The sponge material keeps its own shape. Squashing it just pushes air out of its holes, and it springs back when you let go." },
    { q: "Sand can be poured like a liquid. Why is it still a solid?", a: ["Its tiny grains each keep their shape", "It forms a flat surface like water", "Sand always stays in one big heap", "It can be squashed into a smaller space"], why: "Sand is made of tiny solid grains. Each grain keeps its own shape and size; the pile can be poured only because the grains are separate." },
    { q: "Four sealed syringes are filled with different things. Which one would let you push the plunger in furthest?", a: ["Air", "Water", "Cooking oil", "Candle wax"], why: "Gas particles are far apart, so a gas can be squashed. In liquids and solids the particles are already touching, so they hardly squash at all." },
    { q: "The white cloud just above a boiling kettle's spout is often called steam. What is it really?", a: ["Tiny droplets of liquid water", "Invisible water vapour", "Smoke from the hot kettle", "Air bubbles from the water"], why: "True steam (water vapour) is an invisible gas — look at the clear gap by the spout. The white cloud forms when it cools into tiny water droplets." }
  ],

  // Matter Is Made of Particles
  "mt_ylruY6VhOf": [
    { q: "In which state of matter are the particles packed tightly together in a fixed pattern?", a: ["Solid", "Liquid", "Gas", "Liquid and gas"], why: "In a solid the particles are packed tightly in a regular pattern. They vibrate on the spot but can't move around, so the solid keeps its shape." },
    { q: "Why can't you see the particles that make up water, even with a magnifying glass?", a: ["They are far too small to see", "There are no particles in liquids", "They only exist when water freezes", "They sink to the bottom of the glass"], why: "Everything is made of particles, but they are so tiny that a single drop of water holds more than a billion billion of them." },
    { q: "Why can a liquid flow and be poured?", a: ["Its particles can slide past each other", "Its particles are very far apart", "Its particles are stuck in fixed places", "Its particles are bigger than a solid's"], why: "In a liquid the particles are close together but not fixed in place, so they can slide past one another. That lets the liquid flow." },
    { q: "How are the particles arranged in a gas?", a: ["Far apart, moving fast in all directions", "Touching each other, in neat rows", "Touching, but sliding past each other", "Close together, vibrating in place"], why: "Gas particles are spread far apart and zoom about in all directions. That's why gases spread out to fill any space." },
    { q: "When ice is heated and melts, what happens to its particles?", a: ["They gain energy and move more", "They melt into smaller particles", "They get bigger and softer", "They stop moving altogether"], why: "Heating gives the particles more energy. They vibrate more and more until they break free of their fixed places and can slide around as a liquid." },
    { q: "A drop of food colouring is put in a glass of still water. After a while, the whole glass is coloured. Why?", a: ["Moving particles mix the colour through", "The colour particles grow to fill it", "The water particles stay perfectly still", "Gravity pulls the colour into every part"], why: "Particles in a liquid are always moving and bumping into each other. The colouring particles spread out among the water particles until evenly mixed." },
    { q: "Liam says, \"When water boils, its particles get bigger, so steam takes up more space.\" What is wrong?", a: ["The particles spread apart; they don't grow", "The particles shrink when they turn to gas", "Steam takes up less space than liquid water", "Water has no particles to begin with"], why: "Particles don't change size. When water boils, the particles move much faster and spread far apart, so the gas takes up much more space." },
    { q: "A bike tyre is pumped up on a cold morning. Later, in hot sun, it feels firmer. Why?", a: ["Air particles move faster and push harder", "Air particles get bigger in the heat", "More air leaks into the tyre in the sun", "The rubber particles shrink in the sun"], why: "Heating gives the air particles more energy. They move faster and hit the inside of the tyre harder and more often, so the pressure goes up." }
  ],

  // Evaporation & the Water Cycle
  "mt_Qkewo5M3_c": [
    { q: "What is evaporation?", a: ["A liquid turning into a gas", "A gas turning into a liquid", "A solid turning into a liquid", "A liquid turning into a solid"], why: "Evaporation is when a liquid turns into a gas, such as water turning into water vapour. A gas turning into a liquid is condensation." },
    { q: "Water vapour high in the sky cools and turns into tiny droplets, forming clouds. What is this process called?", a: ["Condensation", "Evaporation", "Precipitation", "Melting"], why: "Condensation is a gas turning into a liquid. When water vapour cools, it condenses into tiny droplets that make clouds." },
    { q: "In the water cycle, what is precipitation?", a: ["Water falling as rain, snow or hail", "Water vapour rising from the sea", "Droplets forming on a cold window", "Rivers carrying water to the sea"], why: "Precipitation is any water falling from clouds: rain, snow, sleet or hail. It then flows back to rivers and the sea." },
    { q: "On which day would a puddle in the playground dry up fastest?", a: ["A warm, sunny, windy day", "A cold, still, cloudy day", "A cold, foggy morning", "A cool, damp evening"], why: "Water evaporates faster when it is warmer, and wind carries the water vapour away. A warm, windy day dries puddles quickest." },
    { q: "In the water cycle, water evaporates from the sea. What happens next?", a: ["It condenses into clouds", "It falls as rain on hills", "It flows down rivers", "It soaks into the soil"], why: "The order is evaporation, condensation, precipitation. Water vapour rises, cools and condenses into clouds, and later falls as rain." },
    { q: "A saucer of water left on a sunny windowsill is empty after a few days. Where has the water gone?", a: ["Into the air as water vapour", "Soaked into the saucer", "It has simply vanished", "Turned into oxygen in the sun"], why: "The water evaporated into the air as invisible water vapour. It hasn't vanished — it could condense back into water somewhere cooler." },
    { q: "A cold can of drink from the fridge soon gets wet on the outside. Where does the water come from?", a: ["Water vapour from the air condensing", "Drink leaking out through the metal", "The metal of the can melting a little", "Ice from the fridge stuck to the can"], why: "Air contains invisible water vapour. When it touches the cold can, it cools and condenses into droplets on the outside." },
    { q: "Rain comes from water that evaporated from the salty sea. Why isn't rain salty?", a: ["Only water evaporates; the salt is left", "Clouds filter the salt out of the rain", "The salt freezes and falls separately", "Rain comes from rivers, not the sea"], why: "When sea water evaporates, only the water turns into vapour. The salt stays behind in the sea, so the clouds and rain are fresh water." }
  ],

  // Dissolving & Solutions
  "mt_Mf-T-fYRLX": [
    { q: "What is a solution?", a: ["A solid fully dissolved in a liquid", "A solid that has sunk to the bottom", "Two dry solids mixed together", "A liquid that has frozen solid"], why: "A solution forms when a substance dissolves completely in a liquid, like salt in water. It looks clear (it may be coloured) and doesn't settle." },
    { q: "Which of these will dissolve in water?", a: ["Sugar", "Sand", "Flour", "Gravel"], why: "Sugar dissolves and seems to vanish. Flour only makes the water cloudy and settles, and sand and gravel sink to the bottom." },
    { q: "When sugar is stirred into tea, you can't see it any more. What has happened to the sugar?", a: ["It has spread out through the tea", "It has disappeared completely from the tea", "It has turned into water in the cup", "It has melted away in the hot tea"], why: "The sugar has dissolved: it has split into particles too small to see, mixed in with the water. You can still taste it, so it hasn't gone." },
    { q: "How could you get the salt back from a bowl of salty water?", a: ["Evaporate the water", "Filter it through paper", "Pour it through a sieve", "Freeze it, then thaw it"], why: "Leave it somewhere warm or heat it gently: the water evaporates and the salt is left behind as crystals. Filtering won't work — dissolved salt passes through." },
    { q: "Which would help sugar dissolve faster in a cup of water?", a: ["Using warmer water and stirring", "Using ice-cold water from the fridge", "Using bigger lumps of sugar", "Leaving the cup very still"], why: "Warmer water and stirring both speed up dissolving. Small grains dissolve faster than big lumps because more of their surface touches the water." },
    { q: "Liam stirs sand into water. The water goes cloudy, then the sand settles at the bottom. Has he made a solution?", a: ["No, the sand has not dissolved", "Yes, it is mixed with water", "Yes, because it went cloudy", "Only while he keeps stirring"], why: "Sand doesn't dissolve. A solution never settles out, and it stays clear rather than cloudy. Sand and water is a mixture you can separate by filtering." },
    { q: "When salt dissolves in water, what is the water called?", a: ["The solvent", "The solute", "The solution", "The sediment"], why: "The liquid that does the dissolving is the solvent (water). The substance that dissolves is the solute (salt). Together they make the solution." },
    { q: "20 g of salt is dissolved in 100 g of water. What is the mass of the salt solution?", a: ["120 g", "100 g", "80 g", "20 g"], why: "No mass is lost when something dissolves. The salt is still there, just spread out, so 100 g + 20 g = 120 g." }
  ],

  // Reversible Changes
  "mt_UKmtuAsSLN": [
    { q: "What is a reversible change?", a: ["The original materials can be got back", "A new material is always made", "It can never be undone in any way", "It only happens when something burns"], why: "In a reversible change no new substance is made, so you can get the original materials back, for example by cooling, heating or evaporating." },
    { q: "Which of these is a reversible change?", a: ["Melting chocolate", "Baking a cake", "Burning toast", "Frying an egg"], why: "Melted chocolate sets again when it cools, and it's still chocolate. Baking, burning and frying make new substances that can't be changed back." },
    { q: "True or false: melting is an irreversible change.", a: ["False", "True"], why: "Melting is reversible. Cool melted wax or chocolate and it becomes solid again as the same substance — no new material has been made." },
    { q: "How could you reverse the change when water freezes into ice cubes?", a: ["Warm the ice so it melts", "Put it back in the freezer", "Crush it into small pieces", "Stir some sugar into it"], why: "Freezing and melting are opposite changes of state. Warming the ice turns it back into liquid water, so freezing is reversible." },
    { q: "Liam dissolves bath salts in a bowl of warm water. Which process would get the bath salts back?", a: ["Evaporating the water", "Filtering the solution", "Pouring it through a sieve", "Stirring it faster"], why: "Dissolving is reversible. Evaporate the water and the salts are left behind as crystals. Filtering won't work because dissolved salts pass through." },
    { q: "Steel paper clips are mixed into a bowl of rice. How could you separate them again?", a: ["Use a magnet", "Evaporate them", "Freeze the mixture", "Burn the mixture"], why: "Steel paper clips are attracted to a magnet but rice isn't. Nothing new was made when they were mixed, so it was a reversible change." },
    { q: "What do all reversible changes have in common?", a: ["No new substance is made", "They all involve heating", "Water is always involved", "They all happen very quickly"], why: "In a reversible change the substances stay the same — only their state or how they are mixed changes. So the change can be undone." },
    { q: "When a candle burns, which of these is a reversible change?", a: ["The wax melting near the flame", "The wick turning black and burning", "The wax vapour burning in the flame", "Smoke rising from the flame"], why: "Melted wax sets again when it cools — still wax. The burning wick and wax vapour make new substances such as carbon dioxide and soot, which can't be undone." }
  ],

  // Irreversible Changes
  "mt_rbPioPELM1": [
    { q: "Which of these is an irreversible change?", a: ["Burning wood", "Melting ice", "Dissolving sugar", "Freezing juice"], why: "Burning makes new substances such as ash, smoke and carbon dioxide, which can't be turned back into wood. The others are reversible." },
    { q: "An iron bike left out in the rain grows orange-brown flakes. What is this change called?", a: ["Rusting", "Melting", "Dissolving", "Evaporating"], why: "Rusting is an irreversible change: iron reacts with oxygen and water to make rust, a new substance that is flaky and weak." },
    { q: "Bicarbonate of soda is added to vinegar and it fizzes. What does the fizzing show?", a: ["A gas is being made", "The vinegar is boiling", "The powder is melting", "Air escaping from the jar"], why: "The bubbles are carbon dioxide, a new gas made by the reaction. Making a new substance is a sign of an irreversible change." },
    { q: "Which of these is **not** a sign that a new substance has been made?", a: ["Something melting as it warms", "Bubbles of a new gas forming", "A sudden change in colour", "Heat or light being given off"], why: "Melting is a change of state, which is reversible. New gases, colour changes and heat or light given off are signs of an irreversible change." },
    { q: "Why can't burnt toast be turned back into bread?", a: ["Burning has made new substances", "The toast is too hot to cool down", "Bread was a solid to start with", "The toast has become a liquid"], why: "Heating the bread so much made new substances, such as black carbon. Cooling or adding water can't turn them back into bread." },
    { q: "Victoria says, \"Cooking an egg is reversible, because you can cool it down again.\" What is wrong?", a: ["Cooling won't make it raw again", "Eggs cannot be cooled down", "Cooking an egg melts it", "Cooling makes it more cooked"], why: "Heat changes the egg's proteins for good, making it solid and white. Cooling it doesn't undo this, so cooking an egg is irreversible." },
    { q: "Iron needs two things to rust. What are they?", a: ["Oxygen and water", "Salt and sunlight", "Heat and darkness", "Sand and wind"], why: "Iron rusts when it reacts with oxygen (from the air) and water. That's why paint, oil or grease, which keep them out, stop iron rusting." },
    { q: "Which gas is made when wood burns in air?", a: ["Carbon dioxide", "Oxygen", "Hydrogen", "Helium"], why: "Burning uses up oxygen and makes new substances, including carbon dioxide, water vapour and ash. They can't be turned back into wood." }
  ],

  // Separating Mixtures
  "mt_2b6CB0w3Yx": [
    { q: "Which method is best for separating gravel from sand?", a: ["Sieving", "Evaporating", "Dissolving", "Freezing"], why: "A sieve has holes big enough for the small sand grains to fall through but too small for the larger gravel stones." },
    { q: "Iron filings are mixed with sand. What is the quickest way to separate them?", a: ["Use a magnet", "Filter the mixture", "Evaporate it", "Add water and stir"], why: "Iron is magnetic but sand isn't, so a magnet pulls out the iron filings and leaves the sand behind." },
    { q: "Which method separates sand from water, so that you can keep both?", a: ["Filtering", "Evaporating", "Using a magnet", "Dissolving"], why: "Filter paper lets the water through but traps the sand grains. Evaporating would leave the sand but lose the water into the air." },
    { q: "Which of these mixtures could be separated with a sieve?", a: ["Dried peas and flour", "Salt dissolved in water", "Sugar dissolved in tea", "Food colouring and water"], why: "A sieve can only separate solid bits of different sizes. Dissolved salt, sugar and food colouring pass straight through with the liquid." },
    { q: "Why does filtering separate sand from water?", a: ["Sand grains are too big to get through", "Sand dissolves into the filter paper", "The water evaporates through the paper", "The paper pulls sand to it like a magnet"], why: "Filter paper has tiny holes. Water particles pass through, but the sand grains are too big, so they stay in the paper." },
    { q: "Why can't filtering separate salt from salty water?", a: ["Dissolved salt passes through the filter", "Salt crystals block the filter paper", "Salt sticks to filter paper like glue", "Water can't pass through filter paper"], why: "Dissolved salt is split into particles far smaller than the holes in filter paper, so they go straight through with the water. Evaporating is needed instead." },
    { q: "A beaker holds a mixture of sand, salt and water. Which plan gets back dry sand and dry salt?", a: ["Filter, then evaporate the liquid", "Evaporate, then filter the solids", "Sieve, then use a magnet", "Freeze, then filter the ice"], why: "Filtering traps the sand. The salty water that passes through is then evaporated, leaving the salt behind as crystals." },
    { q: "Anya filters muddy pond water and it comes through clear. She says it is now safe to drink. Why is she wrong?", a: ["Dissolved things and germs may remain", "Filtering always makes water dirtier", "Filter paper adds salt to the water", "Clear water is never safe to drink"], why: "Filtering removes only solid bits. Dissolved substances and tiny germs can pass through, so filtered pond water still isn't safe to drink." }
  ],

  // Atoms, Elements & Compounds
  "mt_Z_Wu_77ybI": [
    { q: "What is an element?", a: ["A substance made of only one kind of atom", "Two or more kinds of atom joined together", "Any substance that is a solid", "A mixture of different substances"], why: "An element contains only one kind of atom, e.g. gold, oxygen or carbon. Different kinds of atom chemically joined together make a compound." },
    { q: "Which particles are found in the nucleus at the centre of an atom?", a: ["Protons and neutrons", "Electrons and protons", "Electrons only", "Neutrons and electrons"], why: "The tiny nucleus holds the protons and neutrons. The electrons are outside it, moving around the nucleus." },
    { q: "In the simple Bohr model of an atom, where are the electrons?", a: ["In shells around the nucleus", "Inside the nucleus with protons", "Spread evenly through the atom", "Stuck to the outside of protons"], why: "In the Bohr model, electrons are arranged in shells (energy levels) around the central nucleus, a bit like rings around a tiny centre." },
    { q: "How many atoms are in one molecule of water, H₂O?", a: ["3", "2", "1", "4"], why: "H₂ means two hydrogen atoms; O with no number means one oxygen atom. 2 + 1 = 3 atoms in each water molecule." },
    { q: "What does the formula CO₂ tell you?", a: ["One carbon atom joined to two oxygen atoms", "Two carbon atoms joined to one oxygen atom", "One cobalt atom joined to two oxygen atoms", "Two oxygen atoms mixed with some carbon"], why: "C is carbon and O is oxygen; the small 2 applies to the oxygen. (Cobalt would be Co, with a small o.) Carbon dioxide is a compound." },
    { q: "Which of these is a compound?", a: ["Carbon dioxide, CO₂", "Oxygen gas, O₂", "Iron, Fe", "Gold, Au"], why: "A compound has two or more different elements chemically joined. O₂ has two atoms but they are both oxygen, so it is still an element." },
    { q: "Table salt has the formula NaCl. Which two elements is it made from?", a: ["Sodium and chlorine", "Nitrogen and chlorine", "Sodium and calcium", "Nickel and carbon"], why: "Na is the symbol for sodium (from its Latin name, natrium) and Cl is chlorine. Salt is a compound of the two." },
    { q: "Iron filings and yellow sulfur powder are stirred together but not heated. What have you made?", a: ["A mixture", "A compound", "A new element", "A solution"], why: "The iron and sulfur aren't joined, so a magnet can still pull the iron out. Heating them strongly would make a compound, iron sulfide." }
  ],

  // Acids, Alkalis & pH
  "mt_AN2kJE6I0s": [
    { q: "Lemon juice has a pH of about 2. Which word describes it?", a: ["Acidic", "Alkaline", "Neutral", "Salty"], why: "Anything with a pH below 7 is acidic, and the lower the number, the more acidic it is. Lemon juice and vinegar are everyday acids." },
    { q: "Which pH value shows the most acidic solution?", a: ["pH 1", "pH 5", "pH 9", "pH 13"], why: "The lower the pH, the more acidic. pH 1 is strongly acidic, pH 5 weakly acidic, and pH 9 and 13 are alkaline." },
    { q: "Liam says, \"pH 12 must be a strong acid, because 12 is a big number.\" What is his mistake?", a: ["Above pH 7 is alkaline, not acidic", "pH 12 is neutral, the same as water", "The pH scale only goes up to 10", "Only pH 14 counts as a strong acid"], why: "On the pH scale, 7 is neutral, below 7 is acidic and above 7 is alkaline. pH 12 is strongly alkaline." },
    { q: "Blue litmus paper is dipped into a liquid and turns red. What does this show?", a: ["The liquid is an acid", "The liquid is an alkali", "The liquid is neutral", "The liquid is pure water"], why: "Litmus is red in acids and blue in alkalis. Blue litmus turning red is the test for an acid." },
    { q: "A few drops of universal indicator turn a liquid purple. What does this tell you?", a: ["It is very alkaline", "It is very acidic", "It is neutral", "It is slightly acidic"], why: "Universal indicator is red when very acidic, green when neutral and purple when very alkaline, so purple means a high pH, near the top of the scale." },
    { q: "Which of these household liquids is an alkali?", a: ["Bleach", "Vinegar", "Lemon juice", "Cola"], why: "Bleach is strongly alkaline, so it can harm skin and eyes — only adults should use it. Vinegar, lemon juice and cola are all acidic." },
    { q: "A solution of bicarbonate of soda has a pH of about 8. What is it?", a: ["Weakly alkaline", "Weakly acidic", "Neutral", "Strongly alkaline"], why: "A pH just above 7 means weakly alkaline. Bicarbonate of soda is a mild alkali, which is why it is used in some indigestion remedies." },
    { q: "All acids release which ions when they dissolve in water?", a: ["Hydrogen ions, H⁺", "Hydroxide ions, OH⁻", "Sodium ions, Na⁺", "Calcium ions, Ca²⁺"], why: "Acids release hydrogen ions (H⁺) in water. The more H⁺ ions, the more acidic the solution and the lower its pH. Alkalis release hydroxide ions (OH⁻)." }
  ]
});
